    /** Exact frozen selectors used only when migrating a customized old Item Sink tag. */
    public static List<String> legacySelectors(String tagId) {
        var match = java.util.regex.Pattern.compile("item_sink:(?:(original|createcore)/)?value_([0-9]+)").matcher(tagId);
        if (!match.matches()) return null;
        int tier;
        try {
            tier = Integer.parseInt(match.group(2));
        } catch (NumberFormatException invalidTier) {
            return null;
        }
        List<String> original = switch (tier) {
            case 1 -> LEGACY_ORIGINAL_1;
            case 2 -> LEGACY_ORIGINAL_2;
            case 3 -> LEGACY_ORIGINAL_3;
            case 4 -> LEGACY_ORIGINAL_4;
            case 5 -> LEGACY_ORIGINAL_5;
            case 6 -> LEGACY_ORIGINAL_6;
            case 7 -> LEGACY_ORIGINAL_7;
            case 8 -> LEGACY_ORIGINAL_8;
            case 16 -> LEGACY_ORIGINAL_16;
            case 32 -> LEGACY_ORIGINAL_32;
            case 48 -> LEGACY_ORIGINAL_48;
            case 64 -> LEGACY_ORIGINAL_64;
            default -> null;
        };
        List<String> core = switch (tier) {
            case 1 -> LEGACY_CREATECORE_1;
            case 2 -> LEGACY_CREATECORE_2;
            case 3 -> LEGACY_CREATECORE_3;
            case 4 -> LEGACY_CREATECORE_4;
            case 5 -> LEGACY_CREATECORE_5;
            case 6 -> LEGACY_CREATECORE_6;
            case 7 -> LEGACY_CREATECORE_7;
            case 8 -> LEGACY_CREATECORE_8;
            case 16 -> LEGACY_CREATECORE_16;
            case 32 -> LEGACY_CREATECORE_32;
            case 48 -> LEGACY_CREATECORE_48;
            case 64 -> LEGACY_CREATECORE_64;
            default -> null;
        };
        if (original == null) return null;
        if ("original".equals(match.group(1))) return original;
        if ("createcore".equals(match.group(1))) return core;
        var result = new ArrayList<String>(original);
        result.addAll(core);
        return List.copyOf(result);
    }
